### Paso 4: Crear Pruebas Unitarias

#### `login.component.spec.ts`

```typescript
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { FormsModule } from '@angular/forms';
import { By } from '@angular/platform-browser';
import { LoginComponent } from './login.component';

describe('LoginComponent', () => {
  let component: LoginComponent;
  let fixture: ComponentFixture<LoginComponent>;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      declarations: [LoginComponent],
      imports: [FormsModule]
    }).compileComponents();
  });

  beforeEach(() => {
    fixture = TestBed.createComponent(LoginComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('should create', () => {
    expect(component).toBeTruthy();
  });

  it('should have a form with username and password fields', () => {
    const usernameInput = fixture.debugElement.query(By.css('input[name="username"]'));
    const passwordInput = fixture.debugElement.query(By.css('input[name="password"]'));
    expect(usernameInput).toBeTruthy();
    expect(passwordInput).toBeTruthy();
  });

  it('should disable the login button if the form is invalid', () => {
    const loginButton = fixture.debugElement.query(By.css('button')).nativeElement;
    expect(loginButton.disabled).toBeTruthy();
  });

  it('should enable the login button if the form is valid', () => {
    component.username = 'testuser';
    component.password = 'password';
    fixture.detectChanges();

    const loginButton = fixture.debugElement.query(By.css('button')).nativeElement;
    expect(loginButton.disabled).toBeFalsy();
  });

  it('should call onSubmit method when form is submitted', () => {
    spyOn(component, 'onSubmit');

    component.username = 'testuser';
    component.password = 'password';
    fixture.detectChanges();

    const form = fixture.debugElement.query(By.css('form')).nativeElement;
    form.dispatchEvent(new Event('submit'));

    expect(component.onSubmit).toHaveBeenCalled();
  });
});
```

### Paso 5: Ejecutar las Pruebas

Para ejecutar las pruebas, usamos el siguiente comando:

```bash
ng test
```

Esto abrirá el navegador y ejecutará las pruebas unitarias, mostrando los resultados en tiempo real.

### Resumen

Hemos creado un componente de login sencillo y atractivo utilizando Angular, HTML y CSS. Además, hemos implementado pruebas unitarias para verificar la funcionalidad del formulario de login. Las pruebas incluyen la verificación de la existencia de los campos de entrada, la habilitación/deshabilitación del botón de envío y la llamada al método `onSubmit` cuando se envía el formulario.
